<?php require __DIR__.'/../config/db.php';require __DIR__.'/../includes/functions.php';require_admin();$event=active_event($pdo);if(!$event){exit('ไม่พบงานที่เปิดใช้งาน');}$q=$pdo->prepare('SELECT r.full_name,pt.name participant_type,r.org_name,r.representative_name,r.position,r.phone,r.companion_count,r.status,r.department,r.created_at,GROUP_CONCAT(CONCAT(ts.slot_time," ",ts.title) ORDER BY ts.sort_order SEPARATOR " | ") slots FROM registrations r JOIN participant_types pt ON pt.id=r.participant_type_id LEFT JOIN registration_time_slots rts ON rts.registration_id=r.id LEFT JOIN time_slots ts ON ts.id=rts.time_slot_id WHERE r.event_id=? GROUP BY r.id ORDER BY r.created_at DESC');$q->execute([$event['id']]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=ku-join-'.date('Ymd').'.csv');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['ชื่อผู้ลงทะเบียน','ประเภท','ส่วนงาน','ผู้แทน','ตำแหน่ง','โทรศัพท์','ผู้ติดตาม','สถานภาพ','สังกัด','กิจกรรม','ลงทะเบียนเมื่อ']);foreach($q as $r)fputcsv($out,[$r['full_name'],$r['participant_type'],$r['org_name'],$r['representative_name'],$r['position'],$r['phone'],$r['companion_count'],$r['status'],$r['department'],$r['slots'],$r['created_at']]);fclose($out);
